mapper.select:
	    select
		t.CREDIT_RULE_ID , t.CREDIT_TAG_ID , t.AST_TYPE_1 , t.AST_TYPE_2 , t.AST_TYPE_3 ,
		t.AST_TYPE_4 , t.AST_TYPE_5 , t.DEDUCT_OBJ_TYPE , t.REMARK, t1.CREDIT_TAG_NAME,
		t1.CREDIT_TYPE
         from CREDIT_RULE_INFO t
         left join CREDIT_TAG_INFO t1 on t.CREDIT_TAG_ID = t1.CREDIT_TAG_ID


                AND t1.CREDIT_TYPE in

                    #{item}



			         AND t1.CREDIT_TAG_ID in

                    #{item}



				 AND t.AST_TYPE_1 in

					 #{item}



				 AND t.AST_TYPE_2 in

					 #{item}



				 AND t.AST_TYPE_3 in

					 #{item}



				 AND t.AST_TYPE_4 in

					 #{item}



				 AND t.AST_TYPE_5 in

					 #{item}



		  order by t.UPDATE_TIME desc

SELECT CREDIT_TAG_ID id, CREDIT_TAG_NAME text FROM CREDIT_TAG_INFO
AND CREDIT_TAG_ID = #{initValue, jdbcType=VARCHAR}
AND CREDIT_TAG_NAME LIKE CONCAT('%', CONCAT(#{search}, '%'))

		SELECT count(1)
		FROM CREDIT_TAG_INFO A


                    CREDIT_TAG_NAME =#{tagName,jdbcType=VARCHAR}
